    ('71da268c-1c62-439a-b603-5cc1bd0f2f76'::uuid, 'vancomycin', '{"title":"Vancomycin 500mg powder for concentrate for solution for infusion vials — UK Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/product/8759/smpc","publisher":"electronic Medicines Compendium (emc), Datapharm","accessed":"2026-11-19","scope":"Named presentation and route only. Check the relevant product section for the particular indication, population or dose.","reviewNote":"Document and presentation identity checked on 19 November 2026. Full claim-level clinical review remains outstanding."}'::jsonb),
    ('acc06eb9-836c-4780-9f7f-8135bd5df8b8'::uuid, 'vasopressin', '{"title":"Argipressin 20 IU/ml Solution for Injection — UK Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/product/4117/smpc","publisher":"electronic Medicines Compendium (emc), Datapharm","accessed":"2026-11-19","scope":"Named presentation and route only. Check the relevant product section for the particular indication, population or dose.","reviewNote":"Document and presentation identity checked on 19 November 2026. Full claim-level clinical review remains outstanding."}'::jsonb),
    ('9be25633-a786-4fbb-b44a-9ff9310d99d2'::uuid, 'vecuronium', '{"title":"Vecuronium bromide 10 mg powder for solution for injection/infusion — UK Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/product/14772/smpc","publisher":"electronic Medicines Compendium (emc), Datapharm","accessed":"2026-11-19","scope":"Named presentation and route only. Check the relevant product section for the particular indication, population or dose.","reviewNote":"Document and presentation identity checked on 19 November 2026. Full claim-level clinical review remains outstanding."}'::jsonb)
  ) AS matched(id, slug, source) LOOP
    SELECT d.sources INTO STRICT prior FROM public.drugs AS d WHERE d.id=row_record.id AND d.slug=row_record.slug FOR UPDATE;
    IF jsonb_typeof(prior) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Unexpected bibliography for %', row_record.slug; END IF;
    SELECT e INTO existing FROM jsonb_array_elements(prior) e WHERE e->>'url'=row_record.source->>'url' LIMIT 1;
    IF existing IS NULL THEN
      UPDATE public.drugs SET sources=prior || jsonb_build_array(row_record.source) WHERE id=row_record.id AND slug=row_record.slug;
    END IF;
  END LOOP;
END
$named$;

